#include <vector>
using namespace std;

class Solution {
public:
    /**
     * 方法一：雙指標（快慢指標）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int removeElement(vector<int>& nums, int val) {
        int slow = 0;

        for (int fast = 0; fast < nums.size(); fast++) {
            if (nums[fast] != val) {
                nums[slow] = nums[fast];
                slow++;
            }
        }

        return slow;
    }

    /**
     * 方法二：雙指標優化（交換法）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int removeElement_swap(vector<int>& nums, int val) {
        int left = 0;
        int right = nums.size() - 1;

        while (left <= right) {
            if (nums[left] == val) {
                nums[left] = nums[right];
                right--;
            } else {
                left++;
            }
        }

        return left;
    }
};

